def first_bad_version(n, bad):
    def is_bad_version(version):
        return version >= bad

    lo, hi = 1, n

    while lo < hi:
        mid = lo + (hi - lo) // 2
        if is_bad_version(mid):
            hi = mid
        else:
            lo = mid + 1

    return lo

